const NO_SPHINX_SCORE = 0;
const BASE_SPHINX_SCORE = 1;
const BONUS_TYPE_THRESHOLD = 4;
const POINTS_PER_BONUS_TYPE = 2;

const isSphinx = (card: Card): boolean => card.monster === "sphinx";

const countMonsterTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const countTypesBeyondThreshold = (types: number): number =>
  Math.max(types - BONUS_TYPE_THRESHOLD, 0);

export const scoreArmy = (army: Card[]): number => {
  if (!army.some(isSphinx)) return NO_SPHINX_SCORE;
  const bonusTypes = countTypesBeyondThreshold(countMonsterTypes(army));
  return BASE_SPHINX_SCORE + POINTS_PER_BONUS_TYPE * (1 + bonusTypes);
};

