const NO_SPHINX_SCORE = 0;
const BASE_SPHINX_SCORE = 2;
const BONUS_TYPE_THRESHOLD = 4;
const POINTS_PER_BONUS_TYPE = 2;

const isSphinx = (card: Card): boolean => card.monster === "sphinx";

const countMonsterTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const hasBonusTypes = (types: number): boolean => types > BONUS_TYPE_THRESHOLD;

const scoreForTypes = (types: number): number =>
  hasBonusTypes(types)
    ? 1 + POINTS_PER_BONUS_TYPE * (types - BONUS_TYPE_THRESHOLD)
    : BASE_SPHINX_SCORE;

export const scoreArmy = (army: Card[]): number =>
  army.some(isSphinx) ? scoreForTypes(countMonsterTypes(army)) : NO_SPHINX_SCORE;
